import hashlib
import hmac
import os
import secrets
import time
import re
from urllib.parse import urlparse, urlencode, parse_qs
from flask import Flask, request, redirect, session, jsonify, abort

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', secrets.token_hex(32))

# Configuration
OAUTH_PROVIDER = 'https://auth.provider.com'
CLIENT_ID = os.environ.get('OAUTH_CLIENT_ID', 'app-client-id')
CLIENT_SECRET = os.environ.get('OAUTH_CLIENT_SECRET', 'app-client-secret')

# Allowed redirect URIs - strict allowlist
ALLOWED_REDIRECTS = [
    'https://myapp.example.com/callback',
    'https://myapp.example.com/auth/complete',
    'https://staging.example.com/callback',
]

# Pre-compile strict URL pattern
STRICT_URL_PATTERN = re.compile(
    r'^https://[a-z0-9]([a-z0-9\-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9\-]*[a-z0-9])?)*(/[a-z0-9._~\-]*)*$',
    re.IGNORECASE
)

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

def normalize_url(url):
    """Normalize URL for consistent comparison using strict parsing."""
    # First validate with strict regex - reject anything unusual
    if not STRICT_URL_PATTERN.match(url):
        return None

    parsed = urlparse(url)
    # Normalize scheme and host to lowercase
    scheme = parsed.scheme.lower()
    host = parsed.hostname.lower() if parsed.hostname else ''
    port = parsed.port
    path = parsed.path

    # Reject non-standard ports entirely
    if port is not None and port not in (443,):
        return None

    # Remove default port
    port = None

    # Normalize path - remove trailing slash for consistency
    if path != '/' and path.endswith('/'):
        path = path.rstrip('/')

    # Reject path traversal attempts
    if '..' in path or '//' in path:
        return None

    # Reconstruct normalized URL
    normalized = f"{scheme}://{host}{path}"

    return normalized

def is_valid_redirect(redirect_uri):
    """Validate redirect URI against allowlist using normalized exact matching."""
    if not redirect_uri:
        return False

    # Reject any non-printable or non-ASCII characters
    if not all(32 <= ord(c) <= 126 for c in redirect_uri):
        return False

    # Reject backslashes, which can confuse parsers
    if '\\' in redirect_uri:
        return False

    # Parse the URI
    parsed = urlparse(redirect_uri)

    # Must be HTTPS
    if parsed.scheme.lower() != 'https':
        return False

    # Must have a valid host
    if not parsed.hostname:
        return False

    # Reject URLs with credentials
    if parsed.username or parsed.password:
        return False

    # Reject fragments (not allowed in OAuth redirect_uri)
    if parsed.fragment:
        return False

    # Reject query parameters in redirect_uri validation
    if parsed.query:
        return False

    # Normalize and compare against allowlist
    normalized_input = normalize_url(redirect_uri)
    if normalized_input is None:
        return False

    for allowed in ALLOWED_REDIRECTS:
        normalized_allowed = normalize_url(allowed)
        if normalized_allowed and constant_time_compare(normalized_input, normalized_allowed):
            return True

    return False

@app.route('/oauth/authorize')
def authorize():
    """Initiate OAuth2 authorization flow."""
    redirect_uri = request.args.get('redirect_uri', '')

    # Validate the redirect URI
    if not is_valid_redirect(redirect_uri):
        return jsonify({'error': 'invalid_redirect_uri', 
                       'message': 'The redirect URI is not in the allowlist'}), 400

    # Generate CSRF state token
    state = secrets.token_urlsafe(32)
    session['oauth_state'] = state
    session['oauth_redirect'] = redirect_uri
    session['oauth_timestamp'] = time.time()

    # Build authorization URL
    params = {
        'response_type': 'code',
        'client_id': CLIENT_ID,
        'redirect_uri': redirect_uri,
        'state': state,
        'scope': 'openid profile email'
    }

    auth_url = f"{OAUTH_PROVIDER}/authorize?{urlencode(params)}"
    return redirect(auth_url)

@app.route('/oauth/callback')
def callback():
    """Handle OAuth2 callback - exchange code for token."""
    code = request.args.get('code')
    state = request.args.get('state')
    error = request.args.get('error')

    if error:
        return jsonify({'error': error}), 400

    # Verify state
    stored_state = session.pop('oauth_state', None)
    if not stored_state or not state:
        abort(403)

    if not hmac.compare_digest(stored_state.encode(), state.encode()):
        abort(403)

    # Check timestamp (5 minute expiry)
    timestamp = session.pop('oauth_timestamp', 0)
    if time.time() - timestamp > 300:
        abort(403)

    # Get the validated redirect URI from session
    redirect_uri = session.pop('oauth_redirect', None)
    if not redirect_uri:
        abort(400)

    # Exchange code for token (simulated)
    token_data = {
        'access_token': secrets.token_urlsafe(32),
        'token_type': 'Bearer',
        'expires_in': 3600
    }

    return jsonify(token_data)

@app.route('/login/redirect')
def login_redirect():
    """Secondary login endpoint that redirects after authentication."""
    next_url = request.args.get('next', '')

    if not next_url:
        return redirect('/dashboard')

    # Only allow safe relative paths
    # Must start with single slash, no protocol-relative, no backslash tricks
    if re.match(r'^/[a-zA-Z0-9][a-zA-Z0-9/_\-]*$', next_url):
        return redirect(next_url)

    # For absolute URLs, validate against allowlist
    if is_valid_redirect(next_url):
        return redirect(next_url)

    return redirect('/dashboard')

@app.route('/dashboard')
def dashboard():
    return jsonify({'page': 'dashboard', 'user': session.get('user', 'anonymous')})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
